//! Fixtures are generated by the pinned upstream prompt.py, with a model-free
//! fake tokenizer. This tests token/render contracts, not checkpoint parity.
use super::{OrderedJson, PreparedQuestion, Question};

fn object(value: &OrderedJson) -> &[(String, OrderedJson)] {
    match value {
        OrderedJson::Object(entries) => entries,
        _ => panic!("expected object"),
    }
}

#[test]
fn pinned_python_request_to_render_and_readout() {
    let fixtures: serde_json::Value =
        serde_json::from_str(include_str!("fixtures/causal.json")).unwrap();
    for fixture in fixtures["cases"].as_array().unwrap() {
        // Original JSON bytes enter the ordered public parser, not Value maps.
        let request =
            OrderedJson::from_slice(fixture["request"].as_str().unwrap().as_bytes()).unwrap();
        let raw = &object(request.get("questions").unwrap())[0].1;
        let instructions = raw
            .get("instructions")
            .unwrap()
            .as_str()
            .unwrap()
            .to_owned();
        let question = match raw.get("type").unwrap().as_str().unwrap() {
            "choice" => Question::Choice {
                instructions,
                criteria: object(raw.get("criteria").unwrap())
                    .iter()
                    .map(|(key, value)| (key.clone(), value.as_str().map(str::to_owned)))
                    .collect(),
            },
            "score" => Question::Score {
                instructions,
                criteria: match raw.get("criteria").unwrap() {
                    OrderedJson::Array(values) => values
                        .iter()
                        .map(|value| value.as_str().unwrap().to_owned())
                        .collect(),
                    _ => panic!("expected levels"),
                },
            },
            _ => panic!("unsupported fixture type"),
        };
        let prepared = PreparedQuestion::causal(question, |text| {
            Ok(match fixture["overrides"].get(text) {
                Some(value) => value
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|id| id.as_u64().unwrap() as u32)
                    .collect(),
                None => text.bytes().map(u32::from).collect(),
            })
        })
        .unwrap();
        assert_eq!(
            prepared.suffix,
            fixture["suffix"].as_str().unwrap(),
            "{}",
            fixture["name"]
        );
        assert_eq!(
            serde_json::to_value(prepared.readout.groups()).unwrap(),
            fixture["groups"]
        );
        assert_eq!(
            format!(
                "{}\n\n",
                request.get("state").unwrap().state_text().unwrap()
            ),
            fixture["state_block"].as_str().unwrap()
        );
        let temperature = fixture["temperature"].as_f64().unwrap();
        let probabilities = prepared
            .readout
            .probabilities(
                |id| {
                    Ok(fixture["logits"]
                        .get(id.to_string())
                        .map_or(-20.0, |v| v.as_f64().unwrap()))
                },
                temperature,
            )
            .unwrap();
        for (got, expected) in probabilities
            .iter()
            .zip(fixture["probabilities"].as_array().unwrap())
        {
            assert!(
                (got - expected.as_f64().unwrap()).abs() < 1e-14,
                "{}",
                fixture["name"]
            );
        }
        if fixture["name"] == "ordered-unicode-newline" {
            // Mutation sentinel: normalizing first, then softmax(p / T), is not
            // the reference's score calibration. This fixture separates them.
            let raw = prepared
                .readout
                .probabilities(
                    |id| {
                        Ok(fixture["logits"]
                            .get(id.to_string())
                            .map_or(-20.0, |v| v.as_f64().unwrap()))
                    },
                    1.0,
                )
                .unwrap();
            let wrong: Vec<_> = raw.iter().map(|p| (p / temperature).exp()).collect();
            let wrong_first = wrong[0] / wrong.iter().sum::<f64>();
            assert!((probabilities[0] - wrong_first).abs() > 0.1);
        }
    }
}

#[test]
fn empty_choice_rejected_before_tokenizer() {
    let result = PreparedQuestion::causal(
        Question::Choice {
            instructions: "Pick.".into(),
            criteria: vec![],
        },
        |_| panic!("invalid question must not tokenize"),
    );
    assert!(result.is_err());
}
